    [DP
      [D'
        [D [The]]
        [NP
          [N'
            [AdjP
              [Adj' [Adj [opposite]]]
            ]
            [N' [N [team]]]
          ]
        ]
      ]
    ]
    [T'
      [T [had]]
      [VP
        [V'
          [V [had]]
          [SC
            [DP
              [D' [D [her]]]
            ]
            [VP
              [V' [V [duck]]]
            ]
          ]
        ]
      ]
    ]
  ]
]
\end{forest}

\vspace{1cm}

% Parse 2: "duck" as a Noun (Transitive/Possessive)
