[CP
  [TP
    [DP
      [D'
        [D [The]]
        [NP
          [N'
            [AdjP
              [Adj' [Adj [opposite]]]
            ]
            [N' [N [team]]]
          ]
        ]
      ]
    ]
    [T'
      [T [had]]
      [VP
        [V'
          [V [had]]
          [DP
            [D'
              [D [her]]
              [NP
                [N' [N [duck]]]
              ]
