              [n\\children]
            ]
          ]
        ]
      ]
    ]
  ]
]
\end{forest}

\vspace{2em}

% Parse 2: NP-Attachment (Modifier reading)
% "Julius hid [the presents intended for the children]."
\begin{forest}
[ip
  [np
    [n\\Julius]
  ]
  [i'
    [i\\$\emptyset_{\text{Past}}$]
    [vp
      [v'
        [v\\hid]
        [np
          [d\\the]
          [n'
            [n'
              [n\\presents]
            ]
